import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"使用者手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/index.md","filePath":"zh-TW/user-guide/index.md","lastUpdated":1786117994000}'),s={name:"zh-TW/user-guide/index.md"};function n(i,t,l,h,g,d){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="使用者手冊" tabindex="-1">使用者手冊 <a class="header-anchor" href="#使用者手冊" aria-label="Permalink to &quot;使用者手冊&quot;">​</a></h1><p>Lertaro 是一款為 Windows 打造的、鍵盤優先的極速檔案搜尋啟動器。它在背景索引你的本機磁碟(NTFS 和 ReFS 透過各自的變更記錄檔，其他檔案系統則直接監看變化)及網路共用，讓你能在極短時間內跳轉到任意檔案、資料夾或應用程式。</p><p>本手冊涵蓋日常使用所需的一切：</p><ul><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 安裝 Lertaro，了解它的三種搜尋視窗(主視窗/快速視窗/內嵌視窗)。</li><li><strong><a href="./search-syntax.html">搜尋語法</a></strong> —— 模糊比對、排除/精確/前綴/後綴運算子、或組、磁碟機代號定向、路徑模式，以及中文檔名的拼音別名比對。</li><li><strong><a href="./hotkeys.html">熱鍵</a></strong> —— 每一個可設定快捷鍵與硬編碼按鍵，及其預設綁定。</li><li><strong><a href="./actions-and-preview.html">動作選單與預覽</a></strong> —— 類右鍵選單的動作清單，以及 QuickLook 預覽視窗。</li><li><strong><a href="./instant-answers.html">即時答案與關鍵字功能</a></strong> —— 計算機、環境變數、執行命令這些捷徑，以及處理程序管理、視窗切換器、瀏覽器資料、設定搜尋、網頁搜尋、翻譯這類關鍵字觸發的外掛。</li><li><strong><a href="./cli.html">命令列搜尋（lff）</a></strong> —— 可以在終端機裡使用的、fzf 風格的命令列夥伴工具。</li><li><strong><a href="./uri-protocol.html">URI 通訊協定（lertaro://）</a></strong> —— 透過一個連結、別的程式或指令碼，直接跳轉到某次搜尋或某項具體設定。</li><li><strong><a href="./file-manager-support.html">支援的檔案管理員</a></strong> —— Lertaro 可以嵌入、觸發快速導覽、或偵測目前資料夾的檔案管理員和檔案選擇對話方塊都有哪些。</li><li><strong><a href="./settings/">設定項參考</a></strong> —— 每一個設定頁面、每一個分頁、每一項設定，逐條列出。</li><li><strong><a href="./troubleshooting.html">疑難排解</a></strong> —— 常見問題與解決辦法。</li><li><strong><a href="./donate.html">捐款贊助</a></strong> —— 如果 Lertaro 對你有幫助。</li></ul><p>如果是第一次設定 Lertaro，建議從<strong>快速上手</strong>開始閱讀。</p>',5)])])}const m=r(s,[["render",n]]);export{p as __pageData,m as default};
